-- Idempotent, so a preview database that ran this under an earlier draft folder name runs it again as a no-op.
-- Expand: a chat message's and an inbox message's file may be a WebM an agent recorded, held to a video's 4 MB bound rather than a picture's or a file's. Each check only widens, so every row standing passes it; each is written again whole, as the earlier rewrites of these checks were, since the migrator runs a migration in one transaction and a check validated apart would still be scanned under the table's lock.
ALTER TABLE "attachment" DROP CONSTRAINT IF EXISTS "attachment_bytes_bound";--> statement-breakpoint
ALTER TABLE "attachment" ADD CONSTRAINT "attachment_bytes_bound" CHECK (("chat_message_id" is null or octet_length("bytes") <= 1500000 or ("content_type" = 'video/webm' and octet_length("bytes") <= 4000000)) and ("conversation_id" is null or octet_length("bytes") <= 4000000) and (not ("task_id" is not null and num_nonnulls("chat_message_id", "inbox_item_id", "conversation_id", "plan_comment_id") = 0) or octet_length("bytes") <= 1500000));--> statement-breakpoint
ALTER TABLE "attachment" DROP CONSTRAINT IF EXISTS "attachment_inbox_kind";--> statement-breakpoint
ALTER TABLE "attachment" ADD CONSTRAINT "attachment_inbox_kind" CHECK (("inbox_item_id" is null and "kind" is null) or ("inbox_item_id" is not null and (("kind" = 'image' and octet_length("bytes") <= 1500000 and "name" is null and "position" is null and "inbox_message_id" is null) or ("kind" = 'answer' and octet_length("bytes") <= 3000000 and "name" is not null and "position" is not null and "inbox_message_id" is null) or ("kind" = 'message' and (octet_length("bytes") <= 3000000 or ("content_type" = 'video/webm' and octet_length("bytes") <= 4000000)) and "name" is not null and "position" is not null and "inbox_message_id" is not null))));
